'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@animate-ui/react/icons';

type BetweenVerticalEndProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    leftRect: {
      initial: { y: 0, transition: { ease: 'easeInOut', duration: 0.3 } },
      animate: { y: -1.5, transition: { ease: 'easeInOut', duration: 0.3 } },
    },
    arrow: {
      initial: {
        d: 'M7.5 16.5L12.5 11.5',
        transition: { ease: 'easeInOut', duration: 0.3 },
      },
      animate: {
        d: 'M7.5 16.5L13.5 10.5',
        transition: { ease: 'easeInOut', duration: 0.3 },
      },
    },
    rightRect: {
      initial: { x: 0, transition: { ease: 'easeInOut', duration: 0.3 } },
      animate: { x: 1.5, transition: { ease: 'easeInOut', duration: 0.3 } },
    },
    path1: {
      initial: {
        d: 'M20 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V4',
        transition: { ease: 'easeInOut', duration: 0.3 },
      },
      animate: {
        d: 'M21.5 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V2.5',
        transition: { ease: 'easeInOut', duration: 0.3 },
      },
    },
  } satisfies Record<string, Variants>,
  'default-loop': {
    leftRect: {
      initial: { y: 0 },
      animate: {
        y: [0, -1.5, 0],
        transition: { ease: 'easeInOut', duration: 0.6 },
      },
    },
    arrow: {
      initial: { d: 'M7.5 16.5L12.5 11.5' },
      animate: {
        d: [
          'M7.5 16.5L12.5 11.5',
          'M7.5 16.5L13.5 10.5',
          'M7.5 16.5L12.5 11.5',
        ],
        transition: { ease: 'easeInOut', duration: 0.6 },
      },
    },
    rightRect: {
      initial: { x: 0 },
      animate: {
        x: [0, 1.5, 0],
        transition: { ease: 'easeInOut', duration: 0.6 },
      },
    },
    path1: {
      initial: {
        d: 'M20 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V4',
      },
      animate: {
        d: [
          'M20 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V4',
          'M21.5 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V2.5',
          'M20 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V4',
        ],
        transition: { ease: 'easeInOut', duration: 0.6 },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: BetweenVerticalEndProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      {...props}
    >
      <motion.path
        d="M20 18H14C10.2288 18 8.34315 18 7.17157 16.8284C6 15.6569 6 13.7712 6 10V4"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.path1}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M3 5.99998C3 5.99998 5.20947 3.00001 6.00002 3C6.79058 2.99999 9 6 9 6"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.leftRect}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M18 15C18 15 21 17.2095 21 18C21 18.7906 18 21 18 21"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.rightRect}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M7.5 16.5L12.5 11.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.arrow}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function BetweenVerticalEnd(props: BetweenVerticalEndProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  BetweenVerticalEnd,
  BetweenVerticalEnd as BetweenVerticalEndIcon,
  type BetweenVerticalEndProps,
  type BetweenVerticalEndProps as BetweenVerticalEndIconProps,
};
